(function(){
var CTL=[["aud", "Soundcraft EPM6 (6-ch mixer)", "Analog mixer. Each channel strip reads top to bottom: jacks, GAIN, EQ, AUX sends, PAN, PFL/MUTE, PEAK light, fader.", [["GAIN (red knob)", "Sets how hot the signal enters the board.", "Every new mic or source. Set it with PFL pressed so the meters peak in the green/amber and the PEAK light stays off."], ["MIC / LINE / INSERT jacks", "MIC = XLR for mics. LINE = 1/4 inch for synths, laptops, DIs. INSERT = break in the channel for a compressor or gate.", "Plug a mic in the XLR. Use LINE for line-level gear. Leave INSERT empty unless you're adding a processor."], ["HF / MF / LF (EQ)", "Three-band tone control: high, mid, low. Mono channels have a sweepable mid.", "Boomy or muddy: turn LF down. Thin or dull: add HF. Leave flat unless something sounds wrong."], ["AUX 1 / AUX 2 (green, blue)", "Send level from this channel to the aux outputs (stage monitors, headphones, in-ears).", "Someone needs to hear a source in a separate mix. Turn up the aux on that channel."], ["AUX MASTERS PRE / POST", "Switches each aux feed between before-fader (PRE) and after-fader (POST) for all channels.", "PRE: monitor mix stays put when you move the main faders. POST: aux follows the fader."], ["PAN / BAL (yellow)", "Places the channel left or right in the stereo mix. On stereo channels it's a balance control.", "Mono room: center everything. Stereo feed: leave center."], ["PFL", "Pre-Fader Listen. Sends that channel to the headphones and monitor outputs. Main meters then show that channel while the PFL ACTIVE light is on.", "Setting gain, or checking whether a channel has signal, without the room hearing it."], ["MUTE", "Silences the channel in the main mix and the post-mute sends.", "A mic you don't want open, or a quick kill on a feedback source."], ["PEAK light", "Lights when the channel is close to clipping.", "Flashing: turn that channel's GAIN down."], ["Channel fader", "Level of the channel into the main mix and post-fader sends.", "Your normal mixing control."], ["STEREO 1 / STEREO 2 (right-hand channels)", "Stereo line inputs with their own EQ, aux sends and balance. Mono sources go in the left jack.", "Laptops, playback devices, keyboards."], ["PHANTOM POWER (+48 V)", "One switch for the board. Powers condenser mics and some DIs through the XLR.", "Condenser mic or powered DI. Plug the mic in first, then switch it on. Never use it with unbalanced sources."], ["2 TRACK MONITOR / TO MIX", "Controls the 2-track (RCA) playback input. MONITOR sends it to monitors and headphones. TO MIX sends it to the main mix.", "Playing a recording or a track from a device on the RCA jacks."], ["MONITOR and headphone level knobs", "Set the level to the monitor outputs and the headphone jack.", "Raise slowly. Hearing damage is real, especially with PFL on."], ["Main faders (yellow)", "Overall level of the main L/R outputs.", "Master volume for the room."], ["MIX / SOLO meters + PFL ACTIVE light", "Meters show the main mix. When PFL ACTIVE is lit, they show the soloed channel instead.", "Meters look wrong or frozen: check for a stuck PFL."], ["Rear/top jacks: MIX OUT, MONITOR OUT, AUX OUT, INSERT, REC OUT", "MIX OUT XLR feeds the room. MONITOR OUT feeds monitor speakers. AUX OUT feeds a monitor/headphone mix. INSERT is a pre-fader break on the main mix.", "No sound out: confirm the right output is cabled to the right speaker."]], "Manual: manuals/soundcraft-efx-epm-user-guide.md. EPM6 photo and layout checked against the 60-second guide."], ["aud", "Allen & Heath Avantis (FOH console)", "64-channel digital mixer. Two 12-fader banks, 6 layers each. Two touchscreens, each with 3 soft rotaries and a Touch & Turn rotary. Most 'hold-a-key and touch a Name Block' functions use the keys left of the screens.", [["Name Block (touch)", "Selects that channel for the Processing and Routing screens. The selected strip shades green. Each bank holds one selected channel.", "Before you adjust anything on a channel, touch its Name Block."], ["Strip rotary + rotary mode keys", "Rotary can control Gain/Trim, Pan, Sends to the active Mix, or 3 assignable functions. The LED colour shows which: red = Gain, yellow = Pan, the Mix colour = Sends.", "Setting preamp gain without opening a screen."], ["Mute / Muted", "Mute turns the channel off in the main mix and all sends. Muted lights when a DCA or Mute Group is muting it.", "Muted lit but Mute is not: look at the DCA or Mute Group."], ["Mix key (on each strip)", "Puts that channel's sends (or the master) onto the strips or rotaries. The active Mix shows top-right of the Processing screen. Press the active Mix key again to return to the main mix.", "Building or fixing a monitor or aux mix."], ["PAFL", "PFL or AFL: sends the channel to the headphones and monitoring system. Preferences are in Setup / Audio / PAFL.", "Checking a channel quietly without sending it to the PA."], ["Pre (hold) + Name Block", "Toggles that channel's send to the active Mix between pre-fader and post-fader. Touch a master mix Name Block to toggle all channels.", "Monitor mix should ignore the main fader: set it pre-fader."], ["Safes (hold) + Name Block", "Makes a channel safe from Scene recall. Global Safes are on Scenes / Global Safes.", "A channel you don't want a Scene recall to change."], ["Freeze in Layers (hold) + Name Block", "Locks a channel in place across all layers.", "Keep a key channel (like a presenter mic) on the faders on every layer."], ["Copy / Paste / Reset (hold)", "Copy then Paste moves channel processing or a processing block. Reset sets it back to default. Hold Reset and nudge a fader to set it to 0 dB or off.", "Duplicate EQ across mics, or wipe a channel."], ["Assign (hold) + Mix key", "Toggles routing assignment of that channel to that mix on or off.", "Adding or removing a channel from a mix."], ["GEQ (hold) + mix Name Block", "Puts the graphic EQ for that mix on the faders. Touch GEQ again to flip high and low bands.", "Ringing or feedback on a mix."], ["Layer keys + Pk lights", "Switch which 12 channels each bank shows. The red Pk light on a layer lights when any channel on it is within 3 dB of clipping.", "A Pk on a layer you aren't viewing means a channel is clipping somewhere you can't see."], ["SoftKeys (24)", "User-assignable keys. Assigned in Setup / Control / SoftKeys.", "Check what the house setup assigned before you press one."], ["Listen (hold) + touch", "Hold Listen and touch a highlighted area to hear that point in the channel's signal path.", "Finding where in the chain a sound is going wrong."], ["Options (hold) + touch", "Hold Options and touch a highlighted area to configure it.", "Changing how a processing block behaves."], ["Name / dB / IO", "Toggles what the Name Block shows: name, fader level in dB, or the patched socket.", "Finding which socket a channel is patched to."], ["View + Soft Rotaries", "Three soft rotaries per screen. View toggles between the configured sets.", "Quick hands-on control of the selected channel's parameters."], ["Screens: Bank, Processing, Routing, I/O, Ganging, Meters, FX, Scenes, Setup, Utility", "Bank = overview of the assigned channels. Processing = EQ/dynamics. Routing = assignments. I/O = patching. Ganging = link parameters. Meters. FX = 12 RackFX units. Scenes. Setup. Utility (show manager, firmware, calibration).", "Tell me which screen you're on and I'll walk you through it."], ["Power Down", "Utility / Status / Homescreen, touch Power Down, confirm, then turn off the mixer and expanders with their switches.", "End of show. Pulling power can lose recent changes."]], "Manual: manuals/avantis-getting-started-iss5.md (surface) and manuals/avantis-firmware-reference-v1.20.md (full reference)."], ["aud", "Allen & Heath DX168 (stage box)", "16 mic/line inputs, 8 XLR outputs. Gain, pad and +48 V are controlled from the mixer, not on the box.", [["DX A port", "CAT5e link to the mixer. Carries inputs, outputs, preamp control and status.", "Main connection. Use a locking EtherCon cable."], ["DX B port + mode switch", "Switch picks Redundant (second cable to compatible hardware) or Cascade (links a second DX168).", "Normally unused. Cascade needs firmware 1.60 or higher, Redundant needs 1.50."], ["PP light (per input)", "Detects +48 V phantom voltage at the socket, whether it came from the DX168 or another source.", "Checking if a condenser mic is getting phantom."], ["Input / output sockets", "Inputs 1-16 on balanced XLR. 8 balanced XLR outputs at +4 dBu line level. Patching is done on the mixer's I/O screen.", "No signal: check patching on the mixer, not just the cable."], ["Mains input + fuse", "100 to 240 V AC. Built-in universal power supply.", "Dead box: check the fuse and mains lead."]], "Manual: manuals/dx168-getting-started.md."], ["aud", "Shure ULX-D receiver (ULXD4)", "Wireless mic receiver. Front panel left to right: sync button and IR window, LCD, menu buttons, control wheel, LEDs.", [["Sync button + IR window", "Sends the receiver's settings to the transmitter over infrared when the windows are lined up.", "After Scan, or to move a mic to this receiver. The IR port turns red, then SYNC SUCCESS! appears."], ["Scan button", "Finds the best open group or channel. SCAN > GROUP SCAN is the normal run.", "Setting up a room. Turn all transmitters off first, then turn on anything that might cause interference."], ["Menu navigation buttons", "Move through the parameter menus.", "Changing gain, name, group or channel."], ["Control wheel", "Push to select a menu item to edit. Turn to change the value.", "Editing group (G), channel (Ch), frequency (MHz), or gain."], ["RF Diversity LEDs (2)", "Blue = good link. Red = interference. Off = no link to a transmitter. The receiver won't output audio unless one blue LED is lit.", "No audio: first check these LEDs."], ["RF Signal Strength LEDs", "Amber = normal signal. Red = overload (above -25 dBm).", "More than one or two amber with the transmitter off means too much interference, so pick another channel."], ["Audio LEDs", "Show average and peak audio level. Red at the top = overload/limiter.", "Red regularly: lower the transmitter's gain."], ["Encryption icon", "Lit when AES-256 encryption is on (Utilities > Encryption).", "A mic that won't sync or mutes: check encryption match."], ["Network icon", "Lit when connected to other Shure devices on the network.", "Multi-receiver setups. Needs a valid IP address."]], "Manual: manuals/shure-ulxd-user-guide-v6.2.md. Mic playing in the wrong room: re-sync it to the right receiver."], ["aud", "Shure ULX-D transmitters (handheld, bodypack, boundary)", "Handheld and bodypack share the same menu buttons. Boundary and gooseneck bases have their own mute button.", [["Power LED", "Green = on. Red = low battery or battery error. Amber = power switch disabled.", "Mic dead or cutting out: look at the LED color."], ["On/Off switch", "Powers the unit on or off. On boundary and gooseneck bases: press to power on, press and hold to power off.", "Mic dead: confirm it is powered on."], ["IR port", "Line it up with the receiver's IR window during sync.", "Syncing the mic to its receiver."], ["exit / enter / up-down buttons", "exit = back without saving. enter = open a menu or confirm. Up/down scroll and change values.", "Checking or changing the mic's group, channel or gain."], ["Battery compartment", "Uses a Shure rechargeable battery or 2 AA. The handheld has a rotating AA adapter.", "Low battery light: swap it. Don't assume a dead mic is an RF problem."], ["Mute/Active button (boundary, gooseneck)", "Four modes: toggle, push-to-mute (hold to mute), push-to-talk (hold to talk), or disabled. The Mute LED shows green = active, red = muted.", "Presenter says their mic is dead: check the mute mode and LED."], ["Antennas (bodypack)", "Hand-tighten only, no tools.", "Weak signal: check that the antenna is on tight."]], "Manual: manuals/shure-ulxd-user-guide-v6.2.md."], ["aud", "QSC K10 (powered speaker)", "Rear panel controls. Two inputs, two gain knobs, and two EQ switches.", [["Channel A input + MIC/LINE switch", "XLR or 1/4 inch combo jack. MIC/LINE switch changes sensitivity for a microphone. No phantom power is provided.", "Mic straight into the speaker: set MIC. Anything line-level: set LINE."], ["Channel A Gain / Channel B Gain", "Set the level for each input and the amount sent to the Post-Gain Line Output.", "Too quiet or too loud at the source: adjust the gain for that channel."], ["Channel B input", "Line level only. XLR, 1/4 inch, or RCA (phono) jacks.", "Laptop or playback feed."], ["LF switch: NORM / EXT SUB / DEEP", "NORM = normal bass. EXT SUB = 100 Hz high-pass filter. DEEP = extra low-frequency extension without a sub.", "With a subwoofer or when the K10 is a floor monitor: EXT SUB. Alone and need more bass: DEEP."], ["HF switch: FLAT / VOCAL BOOST", "FLAT = factory. VOCAL BOOST = more presence for voice.", "Speech only: VOCAL BOOST. Not for full-range music."], ["Post-Gain Line Output", "Line-level mix of both channels after gain. For feeding another speaker.", "Daisy-chaining. Never connect it back to the same unit."], ["Power LED switch: PWR / OFF / LIMIT", "Front LED shows power, stays dark, or glows brighter when limiting.", "OFF if the glow bothers the audience. LIMIT to watch the limiter from the front."], ["LIMIT (red LED)", "Lights when the limiter is protecting the speaker.", "Constantly lit: turn it down. Lit with both gains at minimum means it needs service."], ["STANDBY (green LED)", "Auto-standby after 5 minutes with no signal. Toggle the power switch to wake it.", "Dead speaker after a quiet period: it's likely in standby, not broken."]], "Manual: manuals/qsc-k-series-user-manual.md."], ["aud", "QSC CP12 (powered speaker)", "Rear panel. Three inputs (A, B, C), two gain knobs, a mic boost button and a contour switch.", [["Input A + C GAIN", "Sets sensitivity for Input A and Input C and the signal sent to the amplifier and MIX OUT.", "Level of a laptop or playback feed."], ["Input B GAIN", "Sets sensitivity for Input B.", "Level of a mic or line source on B."], ["MIC BOOST button + yellow LED", "Adds +25 dB to Input B for a microphone. LED lit = mic level.", "Microphone straight into Input B. Don't use it for line level or it distorts."], ["Contour switch (6 positions)", "Default, Default Ext Sub (80 Hz high-pass), Dance, Dance Ext Sub, Floor Monitor, Speech (Input B only).", "Speech with a handheld or headset on B: Speech. Used as a wedge: Floor Monitor. With a subwoofer: an Ext Sub setting."], ["MIX OUT (post gain)", "XLR line-level mix of A, B and C after gain.", "Feeding a second speaker. Never loop it back into the same unit."], ["LIMITER (red LED)", "Lights when the limiter is protecting the speaker.", "Constant: turn it down."], ["SIG LEDs / POWER LED", "Green SIG = signal present on that input. Blue POWER = on.", "No sound: check SIG first, then the cable."]], "Manual: manuals/qsc-cp-series-user-manual.md. No phantom power on the mic input."], ["vid", "Epson EB-L265F projector", "Control panel on the projector, plus the remote. The A/V Mute lever is on the lens.", [["A/V Mute lever (on lens)", "Slides a shutter over the lens to turn off the picture.", "Picture is black but the projector is on: slide it open."], ["Power button", "Turns the projector on or off.", "Startup and cool-down take a few seconds. Wait for the lights to settle before unplugging."], ["Source Search", "Searches for connected video sources.", "Wrong or no input: press it and wait."], ["Home button", "Opens the Home screen.", "Quick access to source and settings."], ["Menu / Esc / Enter / arrows", "Menu opens the menu system. Esc backs out. Enter selects. Arrows move.", "Changing settings."], ["Volume buttons", "Adjust the built-in speaker volume.", "Not used when sound goes through the room system."], ["Keystone buttons", "Vertical and horizontal keystone adjustment to square up the picture.", "Picture shaped like a trapezoid."], ["Status lights", "Show projector status, warnings and temperature.", "Flashing lights: check the user guide for the pattern."], ["Remote: HDMI / Computer / LAN", "Switch to those inputs.", "Select the right input directly."], ["Remote: Auto", "Auto-adjusts position, tracking and sync for analog signals on the Computer ports.", "Only for analog RGB sources."], ["Remote: Color Mode / Aspect", "Color Mode picks a display mode. Aspect picks the image aspect ratio.", "Picture looks stretched or washed out."], ["Remote: E-Zoom +/-", "Zooms into and out of the image.", "Pointing out a detail."], ["Remote: A/V Mute", "Turns off picture and sound.", "Hide the screen between speakers."], ["Remote: Freeze", "Stops the video image.", "Swapping a laptop without showing it."], ["Remote: Split", "Splits the screen between up to four sources.", "Rarely needed."], ["Remote: ID", "Selects which projector this remote controls.", "Several projectors in a room and the remote controls the wrong one."], ["Remote: Default / Num / User", "Default resets the current setting. Num switches the numeric buttons to number input. User is a custom button.", "Reset an accidental setting."]], "Manual: manuals/epson-eb-l265f-users-guide.md. Specs: 4,600 lm laser, standard throw."], ["com", "Clear-Com FreeSpeak II base station", "Front panel: a headset jack and two channels (A and B) each with a Talk switch and a listen-level encoder, plus partyline enable buttons.", [["Headset connector", "4-pin XLR for a Clear-Com headset. Used with the on-board two-channel intercom.", "Operator headset."], ["Talk A / Talk B", "Hold = talks while held. Quick tap = latches on, tap again to release. LED is red when talking.", "Holding it for a quick word, tapping it for longer."], ["Listen level encoders (A / B)", "Turn clockwise to hear the other party. Fully clockwise = maximum.", "You can't hear a channel: turn up its encoder."], ["Call / Reply", "Press Talk briefly, then Call/Reply to send a call to the port or group assigned to that channel.", "Getting a beltpack's attention."], ["A/B reply button", "Replies to the last caller on A or B.", "Answer someone who just called."], ["Partyline A / B enable buttons", "Turn on power to partyline channel A or B on the rear panel. Audio is always connected. Can be locked.", "Wired partyline stations dead: confirm the enable is on."], ["Hold enable button 8+ seconds", "Starts autonulling for that partyline. Release to begin.", "Partyline line is noisy or humming."], ["Registration (setup)", "Enable registration mode on the base (2 minute timeout). On the beltpack: hold menu for 2 seconds, scroll to SYSTEM CONNECT, press D to select.", "Adding a new beltpack."], ["Setup/Enter rotary", "Turn to navigate. Push to select.", "Menu work on the base."]], "Manual: manuals/freespeak2-base-station-guide.md. Sheet says '5 Channel'; check the beltpack/antenna band label."], ["com", "Clear-Com CS-702 (2-channel main station)", "Two partyline channels, A and B, each with its own controls. Plug a headset in the front panel.", [["Listen level knobs (A / B)", "Set the volume for each channel in the operator's headset. Always active, regardless of talk selection.", "You can't hear a channel: check its listen knob."], ["Talk buttons (A / B)", "Dual-action. Quick press toggles latch on/off. Hold = momentary. Amber = active, blue = not active.", "Short call: hold. Long announcement: tap to latch."], ["Call buttons (A / B)", "Turn on the call lights at all stations on that channel. Flashes red when a remote station calls.", "Getting the attention of someone who removed a headset."], ["Stage Announce", "Sends your headset mic to the stage announce output (balanced line level). Mutes your voice on the intercom while pressed. Also closes a relay.", "Paging the stage."], ["Program volume", "Level of the external program input in your headset.", "Monitoring an audio feed while on comms."], ["Party Line Link", "Joins channels A and B into one combined system.", "Everyone needs to hear everyone."], ["RMK (Remote Mic Kill)", "Removes DC power from both channels for an instant, which clears any latched talk on beltpacks.", "A beltpack stuck open and spilling noise."], ["Term (termination switches)", "Individually selectable audio termination for channel A and B.", "One termination per channel on the line. Too many or none causes bad audio."], ["D.C. Short LED", "Red means a short or overload on the lines. Clears on its own when the fault is removed.", "Dead channel: find the bad cable."], ["Earphone jack", "Parallel with the headset earphone for monitoring or recording.", "Recording the intercom."]], "Manual: manuals/clearcom-cs702-manual.md. Cabling help: manuals/clearcom-partyline-comprehensive-guide.md."], ["com", "Clear-Com RS-601 beltpack", "Single-channel wired beltpack. I don't have its own manual, so this is limited to connectors.", [["4-pin headset connector", "Male 4-pin for the headset.", "Plug the CC-95 headset here."], ["Intercom line connectors", "3-pin female and male loop-through.", "Chain to the next station or back to the main station."], ["2.5 mm AUX headset", "For a small auxiliary headset (see CC-25).", "Rare."], ["RS-232 data connector", "Used for programming with Clear-Com V-pack software.", "Don't open the beltpack. Settings are software, not DIP switches."]], "I couldn't download the RS-601 manual. Send me a photo of the beltpack and I'll label its buttons."], ["vid", "PixelHue P20-DS (LED processor)", "Front panel: 5-inch LCD with a knob, input buttons, layer buttons and a Take button. This is from the P20 manual. The P20-DS shares the P20 front panel.", [["LCD + Knob", "Turn the knob to scroll menus. Press to select.", "Reading status or changing settings."], ["BACK", "Goes up one menu level or cancels. Hold knob + BACK for 3 seconds to lock or unlock the front panel buttons.", "Panel not responding: it may be locked."], ["INPUT 1-14 buttons", "Select an input. LED: dim white = no signal; breathing blue = signal present, not in use; blue = in use.", "Picking which source goes on a layer."], ["LAYER 1-7", "Press to open that layer and its menu. Hold to close it. Dim white = closed; bright blue = open; blinking blue = editing.", "Adding or removing a layer on the screen."], ["PRESET", "Opens the preset menu.", "Recall a saved look."], ["SCALE", "Full-screen scaling for the layer at the back of the stack.", "Make a source fill the whole screen."], ["BKG", "Turns the background on (needs a picture in the gallery). Hold to turn it off.", "Show a background behind the layers."], ["FN", "Custom shortcut button. Can be set to Freeze, FTB (fade to black), Genlock or Capture.", "Check what it's assigned to before pressing."], ["TAKE", "Sends the preview (PVW) content to program (PGM) with the transition.", "Go live with what you set up."], ["PGM / PVW / Cut / FTB / T-bar (concepts)", "PGM = what's live. PVW = what you're preparing. Cut = instant switch. FTB = fade to black. T-bar = manual transition lever.", "Always set up on PVW first, then Take."]], "Manual: manuals/pixelhue-p20-user-manual.md and manuals/pixelhue-p20-p20ds-spec-v1.7.1.md."], ["vid", "NovaStar MX40 Pro (LED controller)", "Small front panel: standby button, 3.5-inch screen, knob and BACK.", [["Standby button", "Powers the unit on or off. Hold 5 seconds or longer to restart.", "Controller frozen: hold to restart."], ["Running indicator", "Solid red = standby. Solid blue = starting. Solid green = running normally. Flashing red = running abnormally.", "Wall is dark: check this light first."], ["Knob", "On the home screen, press to enter the menu. Turn to select or change a value. Press to confirm.", "Menu work."], ["BACK", "Back one level or cancel. Hold knob + BACK for 5 seconds to lock or unlock the buttons.", "Panel not responding: it may be locked."], ["USB 2.0", "For exporting the diagnostic result to a USB drive (NTFS or FAT32 only).", "Support asks for diagnostics."], ["TFT screen", "Shows device status, menus and messages. A lock icon means the buttons are locked.", "Quick check on the unit."]], "Manual: manuals/novastar-mx40-pro-manual.md."], ["lx", "Chauvet Maverick MK1 Hybrid", "Moving head with a touchscreen and 6 control buttons.", [["Up / Down / Left / Right buttons", "Navigate the menu. Up/Down also raise and lower values.", "Setting address or options."], ["Enter / Back", "Enter sets the selected value or opens a menu. Back exits.", "Confirming or backing out."], ["Address", "DMX start address, 000-512.", "Fixture not responding: confirm address matches the console patch."], ["Personality: DMX 27CH or 30CH", "Chooses the number of DMX channels.", "Must match the console profile."], ["Control Mode", "DMX, WDMX (wireless), Art-Net or sACN.", "Wrong protocol means no control."], ["Pan Reverse / Tilt Reverse / Swap X/Y", "Flip the direction of pan or tilt, or swap the axes.", "Fixture moves the wrong way."], ["Screen Reverse / Display Orientation", "Flips the display for hanging upside down. AUTO works it out.", "Display is upside down."], ["Blackout on Pan/Tilt, Color, Gobo move", "Fixture goes dark while that function moves.", "Avoid seeing the wheels or head move on stage."], ["Loss of Data: HOLD / CLOSE", "What the fixture does if DMX drops: hold the last look, or close.", "Choose the safer behavior for the show."], ["Lamp Setting", "Lamp on/off via DMX or on power-up.", "Lamp stays off or won't come on with DMX."], ["Preset Select A/B/C", "Recorded presets.", "Stand-alone use."], ["Auto Test / Reset Function / Factory Settings", "Run a self-test, reset one function, or reset everything.", "Fixture misbehaves: try Reset Function first."], ["Touchscreen Lock", "Locks the screen.", "Panel won't respond."], ["WDMX Reset", "Resets the wireless DMX connection.", "Wireless link problems."]], "Manual: manuals/chauvet-maverick-mk1-hybrid-manual.md."], ["lx", "Chauvet Ovation E-910FC", "LED ellipsoidal. The big setting is the DMX personality (channel count).", [["DMX Address", "Start address, 001-512. The highest allowed depends on the personality.", "Fixture not responding: confirm address."], ["1Ch / 3Ch / 5Ch", "1Ch = dimmer. 3Ch = dimmer, virtual color wheel, color temperature. 5Ch = RGBAL.", "Simple levels or white only."], ["7Ch / 10Ch / 12Ch", "7Ch = dimmer, RGBAL, strobe. 10Ch adds a 16-bit dimmer, virtual color wheel and color temperature. 12Ch adds auto programs.", "Most color work."], ["13Ch / 16Ch / HSV", "13Ch and 16Ch have 16-bit RGBAL. HSV = hue, saturation, value.", "Smooth fades or HSV control."], ["Virtual Color Wheel", "Mimics specific gel colors by value.", "Matching a named gel color."]], "Manual: manuals/chauvet-ovation-e910fc-manual.md. Personality must match the console's fixture profile."], ["lx", "Chauvet WELL Panel", "Wireless, battery-powered IP65 RGBW panel. Controlled by W-DMX, DMX or its own control panel.", [["Menu buttons + display", "Navigate settings.", "Setting address or wireless."], ["Power buttons", "Fixture power.", "Turning on or off."], ["Tilt knobs", "Adjust the panel angle.", "Aiming."], ["Wireless Setting > Operating Mode: Receive", "Sets the panel to receive W-DMX.", "First step to link it."], ["Wireless Setting > W-DMX On/Off", "Turns W-DMX on. A ? in front of the signal bars = searching.", "Link it to the transmitter."], ["Wireless Setting > Receive Reset", "Unpairs it so it can link to a new transmitter. Then press RESET on the transmitter.", "Panel linked to the wrong transmitter."], ["Run Time: 3, 5, 8 or 12 hours", "Limits brightness to hit that battery life. 12 hours is the longest.", "Long show: pick a longer run time."], ["Line Voltage Power Loss mode: Dim Out", "After 5 seconds of lost mains power, the LEDs fade to black over 10 seconds. They return when power returns.", "A plugged-in panel went dark: check mains power."], ["DMX personality", "4, 8, 12, 13 or 21 channel.", "Match the console profile."], ["Charging", "Charge using the provided charger with the panel powered off, between 32 and 95 F. It runs from mains while charging.", "Never charge a hot or swollen battery. Don't charge past 24 hours."]], "Manual: manuals/chauvet-well-panel-manual.md."], ["aud", "Nexo NXAMP 4x4 (amp and controller)", "Four-channel amplifier with speaker processing. Details below come from the NXAMP mk2 manual. Check whether your unit is mk2.", [["Speaker preset area (tap)", "Shows the speaker name, mode and frequency range. Tap to choose a preset for a channel.", "Never change this unless you know the rig."], ["Mute (per channel)", "Mutes one amplifier channel.", "Isolate a speaker."], ["Global Mute (overmute)", "Mutes all channels. Separate from the channel mutes.", "Emergency kill."], ["Output meter (VU)", "Shows amplifier channel output voltage. -60 dB to 0 dB relative to clip.", "Is a channel getting signal?"], ["Gain reduction meter", "Shows speaker protection gain reduction, 0 to 24 dB.", "Above 0: the speaker is being protected, so turn it down."], ["Channel LED: green / orange", "Green = current detected on the output, so a speaker is connected. Orange = speaker being protected.", "Green with no sound: signal is the problem. No green: check speaker cable."], ["Menu navigation buttons", "Move between channel settings pages: volume, delay, gain, Array-EQ.", "Adjusting a channel."], ["Device ID / Device Name", "Identify the unit on the network.", "Finding the right amp in the software."]], "Manual: manuals/nexo-nxamp-mk2-user-manual.md."], ["lx", "Road Hog 4 (lighting console)", "Playback master keys. This covers the keys most likely to matter on a call. Ask me for any other key.", [["Go", "Runs the next cue in the playback.", "Advance the show."], ["Halt", "Stops any fades that are in progress.", "A cue is mid-fade and you need it to stop."], ["Back", "Reverses the running crossfade.", "Return to the previous look."], ["Release", "Releases the master.", "Take a playback off."], ["Assert", "Asserts the master.", "Bring a playback back on top of others."], ["Choose", "Selects that playback. Holding the center Choose key lets you dock playback bars.", "Picking a playback to work on."]], "Manual: manuals/hog4-os-manual-part3.md (playback assignment). Hardware: manuals/road-hog-4-datasheet.md."], ["aud", "Zoom H4essential (recorder)", "Handheld recorder with a built-in XY mic. 32-bit float WAV records loud and quiet sounds without gain adjustments.", [["REC button + light", "Starts recording. Press again to stop.", "Record the session."], ["STOP", "Stops recording or playback. Returns to the Home screen from other screens.", "End a take."], ["PLAY/PAUSE, REW, FF", "Play or pause. REW and FF skip files or marks. Hold to search.", "Listening back."], ["Track buttons + red lights", "Turn tracks on or off. Red = on.", "Choose what's recorded."], ["MIXER button", "Opens the Mixer screen.", "Adjust levels."], ["INPUT 1 / INPUT 2", "XLR or 1/4 inch TRS. Only these two have dual A/D converters.", "Connecting a mic or line feed."], ["MIC/LINE IN jack", "Takes a mic. Supports plug-in power.", "Small mic."], ["PHONE/LINE OUT + VOLUME", "Headphone or line out. Volume sets speaker, headphone or line out.", "Plugging headphones mutes the speaker."], ["POWER/HOLD switch", "Power on/off and disables the buttons.", "Buttons dead: slide it off HOLD."], ["Selection dial + ENTER", "Choose items on screens and confirm.", "Menus."], ["USB-C", "File transfer to a computer, or use as an audio interface.", "Pull the files off."], ["REMOTE connector", "For a ZOOM BTA-1 wireless adapter or timecode.", "Control from the app."]], "Manual: manuals/zoom-h4essential-manual.md."], ["vid", "Blackmagic Micro Converter BiDirectional SDI/HDMI", "No front buttons. It works by itself once powered.", [["Micro USB power", "Powered over USB, for example from a laptop or TV.", "No light on the converter: check USB power."], ["Auto format detection", "Detects SD/HD/3G-SDI and matches the output.", "Nothing to set."], ["One input only", "If only one input is connected, SDI and HDMI outputs both become loop outputs of that signal.", "Feed one signal to both HDMI and SDI gear."], ["Both inputs connected", "Converts HDMI to SDI and SDI to HDMI at the same time, with embedded audio.", "Camera out and return feed."], ["Blackmagic Converters Setup (USB)", "Software over USB for settings.", "Only if a setting needs changing."]], "Manual: manuals/blackmagic-micro-mini-converters-manual-2018.md."]];
var DEP={aud:["Audio","var(--audio)"],vid:["Video","var(--video)"],lx:["Lighting","var(--warn)"],com:["Comms","var(--sdi)"]};
var cur="all",q="";
function strip(h){return String(h).replace(/<[^>]+>/g," ");}
function esc(h){return String(h).replace(/&/g,"&amp;").replace(/</g,"&lt;");}
function hay(c){var h=c[1]+" "+c[2]+" "+c[4]+" "+DEP[c[0]][0];for(var i=0;i<c[3].length;i++)h+=" "+c[3][i].join(" ");return (" "+h).toLowerCase();}
function render(){
 var out=document.getElementById("ctlOut"); if(!out) return;
 var html="",n=0,ts=q?q.split(/\s+/):[];
 for(var i=0;i<CTL.length;i++){
  var c=CTL[i];
  if(cur!=="all"&&c[0]!==cur) continue;
  if(ts.length){var h=hay(c),ok=true;for(var t=0;t<ts.length;t++){if(ts[t]&&h.indexOf(" "+ts[t])<0&&h.indexOf("("+ts[t])<0){ok=false;break;}}if(!ok) continue;}
  n++;
  var col=DEP[c[0]][1];
  html+='<details class="ctlcard" style="border-left-color:'+col+'"'+(ts.length?' open':'')+'><summary><b>'+esc(c[1])+'</b><span class="ctlcount">'+c[3].length+' controls</span></summary>'
   +'<div class="ctldept" style="color:'+col+'">'+DEP[c[0]][0]+'</div><p class="ctlintro">'+esc(c[2])+'</p>';
  for(var j=0;j<c[3].length;j++){
   var r=c[3][j];
   var rh=(" "+r.join(" ")).toLowerCase(),show=true;
   html+='<div class="ctlrow"><div class="ctlh">'+esc(r[0])+'</div><div class="ctld">'+esc(r[1])+'</div><div class="ctlu"><b>Use it when:</b> '+esc(r[2])+'</div></div>';
  }
  html+='<div class="ctltip">'+esc(c[4])+'</div></details>';
 }
 document.getElementById("ctlCount").textContent=n+" of "+CTL.length+" pieces of gear";
 out.innerHTML=html||'<p class="lede">Nothing matches. Try a button name or a brand.</p>';
}
var chips=document.getElementById("ctlChips");
if(chips){
 var d=[["all","All"],["aud","Audio"],["vid","Video"],["lx","Lighting"],["com","Comms"]],ch="";
 for(var i=0;i<d.length;i++) ch+='<button class="btn libchip'+(i===0?" on":"")+'" data-d="'+d[i][0]+'">'+d[i][1]+'</button>';
 chips.innerHTML=ch;
 chips.addEventListener("click",function(e){
  var t=e.target; if(!t.getAttribute||!t.getAttribute("data-d")) return;
  cur=t.getAttribute("data-d");
  var all=chips.querySelectorAll(".libchip"); for(var i=0;i<all.length;i++) all[i].classList.toggle("on",all[i]===t);
  render();
 });
}
var inp=document.getElementById("ctlQ");
if(inp) inp.addEventListener("input",function(){q=inp.value.trim().toLowerCase();render();});
render();
})();
